bool robot_ui_bridge_lcd_check(void)
{
  static uint32_t last_ms;
  static uint32_t redraw_cnt;
  uint32_t now;

  if (!g_ui_ready)
    {
      return false;
    }

  /* 限速：面板还没就绪时，重绘出去的像素同样会被丢弃 ⇒ 标志又会被置上。
   * 不限速的话就变成"每 5ms 渲染一整屏"的死循环，把 LVGL 线程整个占住。
   * 250ms 一次：最多浪费几帧，面板一就绪立刻就是完整的一屏。 */
  now = lv_tick_get();
  if (last_ms != 0 && (uint32_t)(now - last_ms) < 250)
    {
      return false;             /* 标志留着，下一轮再说 */
    }
  last_ms = now;

  if (!sf32lb_lcd_take_content_lost())
    {
      return false;
    }

  lv_obj_invalidate(lv_screen_active());

  redraw_cnt++;
  if (redraw_cnt <= 3)
    {
      printf("[Bridge] 面板内容缺失（丢帧/面板复位）⇒ 整屏重绘第 %u 次\n",
             (unsigned)redraw_cnt);
    }

  return true;
}
